package dev.xclipse.gpulab;
import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.widget.*;
import android.view.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.concurrent.*;
public class MainActivity extends Activity {
 TextView output,status; CheckBox root; ScrollView scroll; final ExecutorService worker=Executors.newSingleThreadExecutor(); final Handler handler=new Handler(Looper.getMainLooper()); boolean live=false,busy=false; String last="", lastVulkan=""; int activeMode=0;String nativeName="";
 static final String[] CANDIDATES={"VK_EXT_memory_budget","VK_KHR_shader_float16_int8","VK_KHR_shader_integer_dot_product","VK_EXT_subgroup_size_control","VK_EXT_mesh_shader","VK_KHR_cooperative_matrix","VK_NV_cooperative_matrix2","VK_AMD_anti_lag","VK_KHR_video_decode_queue","VK_KHR_ray_query","VK_EXT_descriptor_buffer"};
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(12),dp(12),dp(12),dp(8));page.setBackgroundColor(0xff101820);TextView title=new TextView(this);title.setText("XCLIPSE GPU LAB");title.setTextColor(0xff8ce5df);title.setTextSize(23);title.setTypeface(null,Typeface.BOLD);page.addView(title);status=new TextView(this);status.setText("Pesquisa de GPU • auditoria de capacidades v0.2");status.setTextColor(0xffb6c9d4);page.addView(status);root=new CheckBox(this);root.setText("Root opcional: somente leitura do kernel");root.setTextColor(Color.WHITE);page.addView(root);root.setOnCheckedChangeListener((v,on)->{if(on)new AlertDialog.Builder(this).setTitle("Acesso root opcional").setMessage("O aplicativo apenas solicita leitura de sensores e diagnosticos GPU. Nao altera configuracoes, firmware ou SELinux.").setPositiveButton("Continuar",null).setNegativeButton("Cancelar",(a,c)->root.setChecked(false)).show();});
 row(page,"Vulkan profundo",()->nativeScan(0,""),"OpenGL / EGL",()->nativeScan(1,""));row(page,"OpenCL",()->nativeScan(2,""),"Kernel / SGPU",()->{boolean useRoot=root.isChecked();task("Kernel / SGPU",()->Kernel.run(useRoot,true));});row(page,"Bibliotecas ELF",()->{String snapshot=lastVulkan;task("Bibliotecas ELF",()->{String elf=Libraries.scan();return elf+Libraries.compare(snapshot,elf);});},"Extensões",this::chooseProbe);row(page,"Monitor ao vivo",this::toggleLive,"Exportar TXT",this::export);row(page,"Copiar relatório",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("GPU report",last));Toast.makeText(this,"Copiado",Toast.LENGTH_SHORT).show();},"Sobre",()->show("Legenda","ANUNCIADA = API lista a extensão.\nACEITA = criação de dispositivo aceitou a extensão; não prova operações.\nINDÍCIO ELF = texto localizado; não prova implementação.\nNÃO ANUNCIADA = não disponível pela API consultada.\nSensores podem exigir root e dependem da ROM. Nenhuma mudança permanente é feita."));
 scroll=new ScrollView(this);output=new TextView(this);output.setTextColor(0xffe0e9ef);output.setTypeface(Typeface.MONOSPACE);output.setTextSize(12);output.setTextIsSelectable(true);output.setPadding(dp(8),dp(8),dp(8),dp(8));scroll.addView(output);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(page);show("Pronto","Selecione uma consulta. Exporte os relatórios para comparar drivers e ROMs.");}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} void row(LinearLayout p,String a,Runnable x,String b,Runnable y){LinearLayout r=new LinearLayout(this);p.addView(r);for(int i=0;i<2;i++){Button v=new Button(this);v.setText(i==0?a:b);v.setAllCaps(false);v.setTextSize(12);Runnable run=i==0?x:y;v.setOnClickListener(w->run.run());r.addView(v,new LinearLayout.LayoutParams(0,dp(46),1));}}
 void show(String label,String s){last="Xclipse GPU Lab | "+label+"\n"+android.os.Build.MANUFACTURER+" "+android.os.Build.MODEL+" | Android "+android.os.Build.VERSION.RELEASE+" | "+android.os.Build.DISPLAY+"\n"+s;status.setText(label);output.setText(last);}
 void stopLive(){live=false;handler.removeCallbacks(tick);} void nativeScan(int mode,String name){if(busy)return;stopLive();busy=true;activeMode=mode;nativeName=name;status.setText("Consultando em processo isolado...");Intent i=new Intent(this,ProbeActivity.class);i.putExtra("mode",mode);i.putExtra("name",name);startActivityForResult(i,10);}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==10){busy=false;try{if(res==RESULT_OK){String report=new String(Files.readAllBytes(new File(getFilesDir(),"native-report.txt").toPath()),StandardCharsets.UTF_8);if(activeMode==0&&nativeName.isEmpty()){lastVulkan=report;report=Audit.summarize(report);}show(nativeName.isEmpty()?new String[]{"Vulkan profundo","OpenGL / EGL","OpenCL"}[activeMode]:"Teste: "+nativeName,report);}else show("Consulta interrompida",data==null?"Processo de teste encerrou ou foi cancelado. Nenhuma extensão foi ativada globalmente.":data.getStringExtra("error"));}catch(Exception e){show("Erro",e.toString());}}else if(req==20&&res==RESULT_OK&&data!=null&&data.getData()!=null){try(OutputStream s=getContentResolver().openOutputStream(data.getData())){if(s!=null)s.write(last.getBytes(StandardCharsets.UTF_8));Toast.makeText(this,"Relatório exportado",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}}}
 interface Job{String get() throws Exception;}void task(String label,Job job){if(busy)return;stopLive();busy=true;status.setText("Lendo "+label+"...");worker.execute(()->{String s;try{s=job.get();}catch(Throwable e){s=e.toString();}final String report=s;handler.post(()->{busy=false;show(label,report);});});}
 void chooseProbe(){new AlertDialog.Builder(this).setTitle("Investigar extensão Vulkan").setItems(CANDIDATES,(d,i)->nativeScan(0,CANDIDATES[i])).show();}
 final Runnable tick=new Runnable(){public void run(){if(!live||busy)return;busy=true;boolean useRoot=root.isChecked();worker.execute(()->{String s=Kernel.run(useRoot,false);handler.post(()->{busy=false;if(live){show("Monitor GPU • "+new java.text.SimpleDateFormat("HH:mm:ss",java.util.Locale.ROOT).format(new java.util.Date()),s);handler.postDelayed(this,2000);}});});}};
 void toggleLive(){if(live){stopLive();status.setText("Monitor pausado");}else if(!busy){live=true;handler.post(tick);}}
 void export(){stopLive();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/plain");i.putExtra(Intent.EXTRA_TITLE,"xclipse-gpu-report.txt");startActivityForResult(i,20);}
 @Override protected void onStop(){super.onStop();stopLive();} @Override protected void onDestroy(){super.onDestroy();stopLive();worker.shutdownNow();}
}
